import {ToolRegistry} from './registry.js';

describe('ToolRegistry schema compilation', () => {
  // specs/hal-engine-tool-input-validation/spec.md#2
  it('rejects missing required input before calling the executor', async () => {
    const registry = new ToolRegistry();
    let calls = 0;
    const execute = async () => {
      calls += 1;
      return 'sunny';
    };
    registry.register(
      {
        name: 'weather',
        description: 'Weather forecast',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      execute
    );

    const response = await registry.execute('weather', {});

    expect({mentionsRequiredLocation: /location.*required|required.*location/.test(response.result), calls}).toEqual({
      mentionsRequiredLocation: true,
      calls: 0,
    });
  });

  // specs/hal-engine-tool-input-validation/spec.md#3
  it('names a wrong-typed field and its expected type without exposing the value', async () => {
    const registry = new ToolRegistry();
    let calls = 0;
    registry.register(
      {
        name: 'weather',
        description: 'Weather forecast',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}},
      },
      async () => {
        calls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('weather', {location: 123456789});

    expect({
      calls,
      mentionsPath: /[/.]location/.test(response.result),
      mentionsType: response.result.includes('string'),
      leaksValue: response.result.includes('123456789'),
    }).toEqual({calls: 0, mentionsPath: true, mentionsType: true, leaksValue: false});
  });

  // specs/hal-engine-tool-input-validation/spec.md#7
  it('throws at register time naming the tool for an invalid static schema', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'weather',
          description: 'Weather forecast',
          inputSchema: {type: 'not-a-json-schema-type'},
        },
        async () => 'sunny'
      )
    ).toThrow(/weather/);
  });
});

import Ajv from 'ajv';
import type {ErrorObject, ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly validatorOptions = {strict: false, validateFormats: false, allErrors: false};
  private readonly ajv = new Ajv(this.validatorOptions);
  private readonly validators = new WeakMap<object, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  private compileSchema(definition: ToolDefinition): ValidateFunction {
    try {
      let validator = this.validators.get(definition.inputSchema);
      if (!validator) {
        validator = this.ajv.compile(definition.inputSchema);
        this.validators.set(definition.inputSchema, validator);
      }
      return validator;
    } catch (error) {
      throw new Error(`Invalid input schema for tool ${definition.name}`, {cause: error});
    }
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    if (typeof definition !== 'function') this.compileSchema(resolved);
    this.tools.set(resolved.name, {definitionSource: definition, execute});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** See specs/hal-engine-tool-input-validation/spec.md for input rejection and unknown-tool behavior. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const definition = this.resolveDefinition(tool.definitionSource);
    const validate = this.compileSchema(definition);
    if (!validate(input)) {
      const errors = validate.errors ?? [];
      const details = errors.map(error => this.describeValidationError(error)).join('; ');
      log.warn('tool', 'input rejected', {name, details});
      return {result: `Invalid tool input: ${details}`};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }

  private describeValidationError(error: ErrorObject): string {
    const reportedPath = 'instancePath' in error ? error.instancePath : 'dataPath' in error ? error.dataPath : '';
    const path = String(reportedPath || '/');
    const params = error.params as {missingProperty?: unknown; type?: unknown};
    if (error.keyword === 'required') {
      return `${path === '/' ? '' : path}/${String(params.missingProperty)} is required`;
    }
    if (error.keyword === 'type') return `${path} must be ${String(params.type)}`;
    return `${path} failed ${error.keyword}`;
  }
}

